}
STATUS_LABEL = {"expired": "פג תוקף", "expiring": "עומד לפוג", "ok": "בתוקף"}


def dmy(d) -> str:
    if d is None:
        return ""
    return d.strftime("%d.%m.%Y")


def dmy_time(t) -> str:
    return t.strftime("%d.%m.%Y %H:%M:%S") if t else ""


def _date_param(value: Optional[str], name: str) -> Optional[date]:
    if not value:
        return None
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise HTTPException(status_code=400, detail="תאריך לא תקין ב'{}'".format(name))


def _project_of(visitor) -> str:
    return get_project(visitor.properties or {}) or NO_PROJECT


def _project_order(name: str):
    return (name == NO_PROJECT, name)


# ---- the reports ----------------------------------------------------------------


def _visitors_in(db: Session, project: Optional[str]) -> List[models.Visitor]:
    out = []
    for v in db.query(models.Visitor).order_by(models.Visitor.name).all():
        if project and _project_of(v) != project:
            continue
        out.append(v)
    return out


def _range(date_from: Optional[date], date_to: Optional[date]):
    """Default: the last 30 days. Returns (from, to, start_dt, end_dt) with `to` inclusive."""
    today = today_local()
    d_to = date_to or today
    d_from = date_from or (d_to - timedelta(days=29))
    if d_from > d_to:
        raise HTTPException(status_code=400, detail="'מתאריך' מאוחר מ'עד תאריך'")
    return d_from, d_to, datetime.combine(d_from, datetime.min.time()), datetime.combine(
        d_to + timedelta(days=1), datetime.min.time()
    )


def _logs(db: Session, start_dt, end_dt):
    return visible(
        db.query(models.VisitorLog)
        .filter(models.VisitorLog.timestamp >= start_dt)
        .filter(models.VisitorLog.timestamp < end_dt)
    )


def report_activity(db, date_from, date_to, project, action):
    d_from, d_to, start_dt, end_dt = _range(date_from, date_to)
    wanted = ("entry", "exit") if action in (None, "", "both") else None
    vis = {v.dbid: v for v in _visitors_in(db, project)}
    rows = []
    for log in _logs(db, start_dt, end_dt).order_by(models.VisitorLog.timestamp.desc()):
        v = vis.get(log.visitor_dbid)
        if v is None:
            continue
        a = norm_action(log.action)
        if wanted is not None and a not in wanted:
            continue
        if action in ("entry", "exit") and a != action:
            continue
        rows.append(
            [dmy_time(log.timestamp), v.name, v.visitorid, _project_of(v), action_label(log.action)]
        )
    return {
        "title": TYPES["activity"],
        "subtitle": ["תקופה: {} - {}".format(dmy(d_from), dmy(d_to))]
        + (["פרויקט: " + project] if project else []),
        "columns": ["תאריך ושעה", "שם", "מספר זיהוי", "פרויקט", "פעולה"],
        "rows": rows,
    }


def report_project_summary(db, date_from, date_to, project):
    d_from, d_to, start_dt, end_dt = _range(date_from, date_to)
    stats: Dict[str, dict] = {}
    by_id = {}
    for v in _visitors_in(db, project):
        p = _project_of(v)
        s = stats.setdefault(p, {"vis": 0, "inside": 0, "en": 0, "ex": 0, "uniq": set()})
        s["vis"] += 1
        if v.inside:
            s["inside"] += 1
        by_id[v.dbid] = p
    for log in _logs(db, start_dt, end_dt):
        p = by_id.get(log.visitor_dbid)
        if p is None:
            continue
        a = norm_action(log.action)
        if a == "entry":
            stats[p]["en"] += 1
            stats[p]["uniq"].add(log.visitor_dbid)
        elif a == "exit":
            stats[p]["ex"] += 1
    rows = []
    tot = [0, 0, 0, 0, 0]
    for p in sorted(stats, key=_project_order):
        s = stats[p]
        vals = [s["vis"], s["inside"], s["en"], s["ex"], len(s["uniq"])]
        rows.append([p] + vals)
        tot = [a + b for a, b in zip(tot, vals)]
    if len(rows) > 1:
        rows.append(['סה"כ'] + tot)
    return {
        "title": TYPES["project_summary"],
        "subtitle": ["תקופה: {} - {}".format(dmy(d_from), dmy(d_to))]
        + (["פרויקט: " + project] if project else []),
        "columns": ["פרויקט", "מבקרים רשומים", "בפנים כרגע", "כניסות", "יציאות", "מבקרים שונים שנכנסו"],
        "rows": rows,
    }


def report_visitors(db, project):
    last_entry = {
        d: t
        for d, t in visible(
            db.query(models.VisitorLog.visitor_dbid, func.max(models.VisitorLog.timestamp)).filter(
                func.lower(func.trim(models.VisitorLog.action)) == "entry"
            )
        )
        .group_by(models.VisitorLog.visitor_dbid)
        .all()
    }
    rows = []
    vis = sorted(_visitors_in(db, project), key=lambda v: (_project_order(_project_of(v)), v.name or ""))
    for v in vis:
        props = v.properties or {}
        rows.append(
            [
                v.name,
                v.visitorid,
                _project_of(v),
                get_value(props, INFOSEC_KEY) or "",
                dmy(parse_date(get_value(props, INFOSEC_EXPIRY_ALIASES))),
                dmy(parse_date(get_value(props, CLASSIFICATION_EXPIRY_ALIASES))),
                "בפנים" if v.inside else "בחוץ",
                dmy_time(last_entry.get(v.dbid)),
            ]
        )
    return {
        "title": TYPES["visitors"],
        "subtitle": ["פרויקט: " + (project or "כל הפרויקטים")],
        "columns": ["שם", "מספר זיהוי", "פרויקט", "אבטחת מידע", "תוקף אישור", 'תוקף סב"ט', "מצב", "כניסה אחרונה"],
        "rows": rows,
    }


def _infosec_class(props) -> str:
    """approved / exception / denied / none (no value) / other (an old free-text value)."""
    raw = get_value(props or {}, INFOSEC_KEY)
    if raw is None:
        return "none"
    if raw == INFOSEC_APPROVED:
        return "approved"
    if raw == INFOSEC_EXCEPTION:
        return "exception"
    if raw == INFOSEC_DENIED:
        return "denied"
    return "other"


def _infosec_match(props, flt) -> bool:
    if not flt or flt == "all":
        return True
    if flt not in INFOSEC_FILTERS:
        raise HTTPException(status_code=400, detail="סטטוס אבטחת מידע לא מוכר")
    cls = _infosec_class(props)
    if flt == "approved_any":
        return cls in ("approved", "exception")
    return cls == flt


def _check_sort(sort, default):
    sort = sort or default
    if sort not in SORTS:
        raise HTTPException(status_code=400, detail="מיון לא מוכר")
    return sort


def report_infosec(db, date_from, date_to, project, infosec, sort):
    """One row per visitor, by information-security status; filter by status / project / approval date."""
    sort = _check_sort(sort, "project")
    if date_from and date_to and date_from > date_to:
        raise HTTPException(status_code=400, detail="'מתאריך' מאוחר מ'עד תאריך'")
    today = today_local()
    warn = get_int_setting(db, KEY_EXPIRY_DAYS, DEFAULT_EXPIRY_DAYS)
    ctx = InviterContext(db)
    items = []
    counts = {"approved": 0, "exception": 0, "denied": 0, "none": 0, "other": 0}
    for v in _visitors_in(db, project):
        props = v.properties or {}
        if not _infosec_match(props, infosec):
            continue
        d = parse_date(get_value(props, INFOSEC_EXPIRY_ALIASES))
        if (date_from or date_to) and d is None:
            continue
        if date_from and d < date_from:
            continue
        if date_to and d > date_to:
            continue
        cls = _infosec_class(props)
        counts[cls] += 1
        if d is None:
            days, label = None, ""
        else:
            days = (d - today).days
            label = STATUS_LABEL["expired" if days < 0 else ("expiring" if days <= warn else "ok")]
        items.append((v, cls, d, days, label, ctx.of(props)))
    if sort == "name":
        items.sort(key=lambda t: t[0].name or "")
    elif sort == "status":
        items.sort(key=lambda t: (_STATUS_RANK[t[1]], _project_order(_project_of(t[0])), t[0].name or ""))
    elif sort == "expiry":
        items.sort(key=lambda t: (t[3] is None, t[3] if t[3] is not None else 0, t[0].name or ""))
    else:
        items.sort(key=lambda t: (_project_order(_project_of(t[0])), t[0].name or ""))
    rows = [
        [
            v.name,
            v.visitorid,
            _project_of(v),
            get_value(v.properties or {}, INFOSEC_KEY) or "ללא סטטוס",
            dmy(d),
            days if days is not None else "",
            label,
            who,
        ]
        for v, _cls, d, days, label, who in items
    ]
    sub = ["נכון לתאריך: " + dmy(today), "אבטחת מידע: " + INFOSEC_FILTERS[infosec or "all"], "מיון: " + SORTS[sort]]
    if date_from or date_to:
        sub.append("תאריך תוקף האישור בין {} ל-{}".format(dmy(date_from) or "...", dmy(date_to) or "..."))
    if project:
        sub.append("פרויקט: " + project)
    sub.append(
        "בדוח: {} | מאושר {} | מאושר חריג {} | לא מאושר {} | ללא סטטוס {}{}".format(
            len(rows), counts["approved"], counts["exception"], counts["denied"], counts["none"],
            " | ערכים ישנים {}".format(counts["other"]) if counts["other"] else "",
        )
    )
    return {
        "title": TYPES["infosec"],
        "subtitle": sub,
        "columns": ["שם", "מספר זיהוי", "פרויקט", "אבטחת מידע", "תוקף אישור", "ימים לתוקף", "מצב תוקף", "מזמין"],
        "rows": rows,
    }


def report_infosec_summary(db, project):
    """Per project: how many visitors hold each information-security status."""
    acc: Dict[str, dict] = {}
    for v in _visitors_in(db, project):
        a = acc.setdefault(_project_of(v), {"approved": 0, "exception": 0, "denied": 0, "none": 0, "other": 0})
        a[_infosec_class(v.properties)] += 1
    rows = []
    tot = [0, 0, 0, 0, 0, 0]
    for p in sorted(acc, key=_project_order):
        a = acc[p]
        vals = [a["approved"], a["exception"], a["denied"], a["none"], a["other"], sum(a.values())]
        rows.append([p] + vals)
        tot = [x + y for x, y in zip(tot, vals)]
    if len(rows) > 1:
        rows.append(['סה"כ'] + tot)
    return {
        "title": TYPES["infosec_summary"],
        "subtitle": ["נכון לתאריך: " + dmy(today_local())] + (["פרויקט: " + project] if project else []),
        "columns": ["פרויקט", INFOSEC_APPROVED, INFOSEC_EXCEPTION, INFOSEC_DENIED, "ללא סטטוס", "ערך ישן אחר", 'סה"כ'],
        "rows": rows,
    }


def report_expiry(db, date_from, date_to, project, field, status, warn_days, infosec=None, sort=None):
    if field not in EXPIRY_FIELDS:
        raise HTTPException(status_code=400, detail="סוג תוקף לא מוכר")
    if status not in (None, "", "all", "expired", "expiring", "ok"):
        raise HTTPException(status_code=400, detail="סטטוס לא מוכר")
    if date_from and date_to and date_from > date_to:
        raise HTTPException(status_code=400, detail="'מתאריך' מאוחר מ'עד תאריך'")
    sort = _check_sort(sort, "expiry")
    today = today_local()
    if warn_days is None:
        warn_days = get_int_setting(db, KEY_EXPIRY_DAYS, DEFAULT_EXPIRY_DAYS)
    groups = (
        [(k, v[0], v[1]) for k, v in EXPIRY_FIELDS.items() if k != "all"]
        if field == "all"
        else [(field, EXPIRY_FIELDS[field][0], EXPIRY_FIELDS[field][1])]
    )
    rows = []
    unreadable = 0
    for v in _visitors_in(db, project):
        props = v.properties or {}
        if not _infosec_match(props, infosec):
            continue
        for _k, label, aliases in groups:
            key = find_key(props, aliases)
            if key is None:
                continue
            d = parse_date(props[key])
            if d is None:
                unreadable += 1
                continue
            days_left = (d - today).days
            st = "expired" if days_left < 0 else ("expiring" if days_left <= warn_days else "ok")
            if status in ("expired", "expiring", "ok") and st != status:
                continue
            if date_from and d < date_from:
                continue
            if date_to and d > date_to:
                continue
            rows.append(
                [
                    v.name,
                    v.visitorid,
                    _project_of(v),
                    label,
                    dmy(d),
                    days_left,
                    STATUS_LABEL[st],
                    get_value(props, INFOSEC_KEY) or "",
                ]
            )
    if sort == "name":
        rows.sort(key=lambda r: (r[0] or "", r[5]))
    elif sort == "project":
        rows.sort(key=lambda r: (_project_order(r[2]), r[5], r[0] or ""))
    elif sort == "status":
        rank = {STATUS_LABEL["expired"]: 0, STATUS_LABEL["expiring"]: 1, STATUS_LABEL["ok"]: 2}
        rows.sort(key=lambda r: (rank.get(r[6], 3), r[5], r[0] or ""))
    else:
        rows.sort(key=lambda r: (r[5], r[0] or ""))
    sub = ["נכון לתאריך: " + dmy(today), "סוג תוקף: " + EXPIRY_FIELDS[field][0], "מיון: " + SORTS[sort]]
    if infosec and infosec != "all":
        sub.append("אבטחת מידע: " + INFOSEC_FILTERS[infosec])
    if status in ("expired", "expiring", "ok"):
        sub.append("סטטוס: {}{}".format(STATUS_LABEL[status], " (עד {} ימים)".format(warn_days) if status == "expiring" else ""))
    if date_from or date_to:
        sub.append("תאריך תוקף בין {} ל-{}".format(dmy(date_from) or "...", dmy(date_to) or "..."))
    if project:
        sub.append("פרויקט: " + project)
    if unreadable:
        sub.append("{} ערכי תוקף לא נקראו (תאריך לא תקין) ולא נכללו".format(unreadable))
    return {
        "title": TYPES["expiry"],
        "subtitle": sub,
        "columns": ["שם", "מספר זיהוי", "פרויקט", "סוג תוקף", "תאריך תוקף", "ימים לתוקף", "סטטוס", "אבטחת מידע"],
        "rows": rows,
    }


def _opt_range(date_from, date_to):
    """An optional range: (from, to, start_dt, end_dt), all None when no date was given."""
    if not date_from and not date_to:
        return None, None, None, None
    if date_from and date_to and date_from > date_to:
        raise HTTPException(status_code=400, detail="'מתאריך' מאוחר מ'עד תאריך'")
    start = datetime.combine(date_from, datetime.min.time()) if date_from else None
    end = (
        datetime.combine(date_to + timedelta(days=1), datetime.min.time())
        if date_to
        else None
    )
    return date_from, date_to, start, end


def _range_text(d_from, d_to) -> str:
    if not d_from and not d_to:
        return "כל התקופות"
    return "{} - {}".format(dmy(d_from) or "...", dmy(d_to) or "...")


def _entries_by_visitor(db, start_dt, end_dt):
    q = visible(
        db.query(models.VisitorLog.visitor_dbid, func.count(models.VisitorLog.id)).filter(
            func.lower(func.trim(models.VisitorLog.action)) == "entry"
        )
    )
    if start_dt is not None:
        q = q.filter(models.VisitorLog.timestamp >= start_dt)
    if end_dt is not None:
        q = q.filter(models.VisitorLog.timestamp < end_dt)
    return {d: n for d, n in q.group_by(models.VisitorLog.visitor_dbid).all()}


def _inviter_match(ctx, v, inviter) -> bool:
    return not inviter or norm(ctx.of(v.properties or {})) == norm(inviter)


def report_invitees(db, date_from, date_to, project, inviter):
    d_from, d_to, start_dt, end_dt = _opt_range(date_from, date_to)
    ctx = InviterContext(db)
    entries = _entries_by_visitor(db, start_dt, end_dt)
    last_entry = {
        d: t
        for d, t in visible(
            db.query(models.VisitorLog.visitor_dbid, func.max(models.VisitorLog.timestamp)).filter(
                func.lower(func.trim(models.VisitorLog.action)) == "entry"
            )
        )
        .group_by(models.VisitorLog.visitor_dbid)
        .all()
    }
    picked = []
    for v in _visitors_in(db, project):
        if not _inviter_match(ctx, v, inviter):
            continue
        n = entries.get(v.dbid, 0)
        if (d_from or d_to) and n == 0:
            continue  # with a date range: only the invitees who actually came in that period
        picked.append((ctx.of(v.properties or {}), v, n))
    picked.sort(key=lambda r: (r[0] == NO_INVITER, r[0], r[1].name or ""))
    rows = [
        [
            who,
            v.name,
            v.visitorid,
            _project_of(v),
            n,
            dmy_time(last_entry.get(v.dbid)),
            "בפנים" if v.inside else "בחוץ",
        ]
        for who, v, n in picked
    ]
    sub = ["תקופה: " + _range_text(d_from, d_to)]
    sub.append("מזמין: " + (inviter or "כל המזמינים"))
    if project:
        sub.append("פרויקט: " + project)
    return {
        "title": TYPES["invitees"],
        "subtitle": sub,
        "columns": ["מזמין", "שם", "מספר זיהוי", "פרויקט", "כניסות" + (" בתקופה" if d_from or d_to else ""), "כניסה אחרונה", "מצב"],
        "rows": rows,
    }


def report_inviter_summary(db, date_from, date_to, project, inviter):
    d_from, d_to, start_dt, end_dt = _opt_range(date_from, date_to)
    ctx = InviterContext(db)
    entries = _entries_by_visitor(db, start_dt, end_dt)
    acc: Dict[str, dict] = {}
    for v in _visitors_in(db, project):
        if not _inviter_match(ctx, v, inviter):
            continue
        who = ctx.of(v.properties or {})
        a = acc.setdefault(who, {"vis": 0, "inside": 0, "en": 0, "uniq": 0})
        a["vis"] += 1
        a["inside"] += 1 if v.inside else 0
        n = entries.get(v.dbid, 0)
        a["en"] += n
        a["uniq"] += 1 if n else 0
    rows = []
    tot = [0, 0, 0, 0]
    for who in sorted(acc, key=lambda w: (w == NO_INVITER, w)):
        a = acc[who]
        vals = [a["vis"], a["inside"], a["en"], a["uniq"]]
        rows.append([who] + vals)
        tot = [x + y for x, y in zip(tot, vals)]
    if len(rows) > 1:
        rows.append(['סה"כ'] + tot)
    sub = ["תקופה: " + _range_text(d_from, d_to)]
    if project:
        sub.append("פרויקט: " + project)
    return {
        "title": TYPES["inviter_summary"],
        "subtitle": sub,
        "columns": ["מזמין", "מוזמנים רשומים", "בפנים כרגע", "כניסות", "מוזמנים שונים שנכנסו"],
        "rows": rows,
    }


