def build_xlsx(report: dict) -> bytes:
    wb = Workbook()
    ws = wb.active
    ws.title = "דוח"
    ws.sheet_view.rightToLeft = True
    ws["A1"] = report["title"]
    ws["A1"].font = _TITLE_FONT
    r = 2
    for line in report["subtitle"] + ["הופק: " + datetime.now().strftime("%d.%m.%Y %H:%M")]:
        ws.cell(row=r, column=1, value=line).font = Font(size=10, color="555555")
        r += 1
    r += 1
    head = r
    for c, name in enumerate(report["columns"], start=1):
        cell = ws.cell(row=head, column=c, value=name)
        cell.fill = _HEADER_FILL
        cell.font = _HEADER_FONT
        cell.alignment = Alignment(horizontal="right")
    widths = [len(str(c)) + 4 for c in report["columns"]]
    for row in report["rows"][:EXPORT_ROWS]:
        r += 1
        for c, value in enumerate(row, start=1):
            ws.cell(row=r, column=c, value=value).alignment = Alignment(horizontal="right")
            widths[c - 1] = min(46, max(widths[c - 1], len(str(value)) + 2))
    for c, w in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(c)].width = max(12, w)
    ws.freeze_panes = ws.cell(row=head + 1, column=1)
    if report["rows"]:
        ws.auto_filter.ref = "A{}:{}{}".format(head, get_column_letter(len(report["columns"])), r)
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


