FLAG_REQUIRE_INVITER = "visitors.require_inviter"
KEY_INVITER_KEY = "visitors.inviter_key"
DEFAULT_KEY = "מזמין"
KNOWN_ALIASES = (
    "מזמין",
    "המזמין",
    "שם המזמין",
    "שם מזמין",
    "גורם מזמין",
    "מארח",
