def _check_name(db: Session, name: str, own_id: Optional[int] = None) -> str:
    name = clean(name)
    if not name:
        raise HTTPException(status_code=400, detail="חובה להזין שם מזמין")
    if len(name) > MAX_NAME:
        raise HTTPException(status_code=400, detail="שם המזמין ארוך מדי")
    for i in db.query(Inviter).all():
        if i.id != own_id and norm(i.name) == norm(name):
            raise HTTPException(status_code=409, detail="המזמין כבר קיים ברשימה (כפילות)")
