def _groups(db: Session) -> dict:
    ctx = Context(db)
    variants: Dict[str, Counter] = {}
    without = 0
    for (props,) in db.query(models.Visitor.properties).all():
        text = raw_value(props or {}, ctx.aliases, exact=True)
        if text is None:
            without += 1
            continue
        variants.setdefault(norm(text), Counter())[text] += 1
    groups = []
    for n, c in variants.items():
        listed = ctx.by_norm.get(n)
        # the spelling to keep: the list's, else the most common one (ties: the shorter, then A-Z)
        best = listed.name if listed else sorted(c.items(), key=lambda kv: (-kv[1], len(kv[0]), kv[0]))[0][0]
        groups.append(
            {
                "canonical": best,
                "total": sum(c.values()),
                "in_list": listed is not None,
                "variants": [
                    {"text": t, "count": k} for t, k in sorted(c.items(), key=lambda kv: -kv[1])
                ],
                "needs_unify": any(t != best for t in c),
            }
        )
    groups.sort(key=lambda g: (-g["total"], g["canonical"]))
    return {
        "key": configured_key(db),
        "aliases": list(ctx.aliases),
        "without_inviter": without,
        "groups": groups,
    }


@router.get("/migration/preview", dependencies=[_ADMIN])
